    policy_text=$(git -C "$REPO" show "$policy_commit:.sailor/delivery-policy.json") || { echo "main at $policy_commit carries no .sailor/delivery-policy.json" >&2; exit 1; }
    printf '%s' "$policy_text" | POLICY_COMMIT="$policy_commit" python3 -c '
import json, os, sys
try:
    policy = json.load(sys.stdin)
except ValueError:
    sys.exit("the delivery policy on main is not JSON")
if not isinstance(policy, dict):
    sys.exit("the delivery policy on main is not an object")
lines = []
for field in ("merge", "push", "release"):
    if policy.get(field) not in ("auto", "ask"):
        sys.exit("the delivery policy on main does not say auto or ask for %s" % field)
    lines.append("%s: %s" % (field, policy[field]))
lines.append(os.environ["POLICY_COMMIT"])
print("\n".join(lines))
'
}
cd "$REPO"
said=$(trusted_policy) || exit 1
printf '%s\n' "$said" | python3 -c '
import json, sys
lines = [line.strip() for line in sys.stdin if line.strip()]
fields = dict(line.split(": ", 1) for line in lines[:-1])
for key in ("merge", "push", "release"):
    if fields.get(key) not in ("auto", "ask"):
        sys.exit("the policy does not say auto or ask for " + key)
print(json.dumps({
    "merge": fields["merge"], "push": fields["push"], "release": fields["release"],
    "read_from": lines[-1],
    "asks_publication": "ask" if fields["push"] == "ask" else "auto",
    "asks_integration": "ask" if "ask" in (fields["merge"], fields["push"]) else "auto",
    "asks_release": "ask" if "ask" in (fields["release"], fields["push"]) else "auto",
}))
'

